SELECT p.gender, p.anchor_year, p.anchor_year_group, i.careunit, i.los, COUNT(DISTINCT d.diagnosis_id) AS num_diagnoses, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) AS num_deaths, AVG(COUNT(d.diagnosis_id)) OVER (PARTITION BY p.gender, p.anchor_year, p.anchor_year_group, i.careunit, i.los) AS avg_comorbidity_count FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.stay_id = i.stay_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id AND a.hadm_id = d.hadm_id WHERE p.gender = 'M' AND p.anchor_year BETWEEN 82 AND 92 AND p.anchor_year_group IN (0, 1, 2, 3) AND i.los <= 5 AND (SELECT COUNT(diagnosis_id) FROM diagnoses_icd WHERE subject_id = p.subject_id AND hadm_id = a.hadm_id) > 1 GROUP BY p.gender, p.anchor_year, p.anchor_year_group, i.careunit, i.los ORDER BY p.gender, p.anchor_year, p.anchor_year_group, i.careunit, i.los NULLS LAST;